/* Standalone reference entries and traditional attributions for all 78 cards.
   The reading copy in birth-lore.js and tarot-readings.js is written for a card in a
   spread position; this module is what a card means on its own. Attributions follow the
   Golden Dawn with Waite's numbering; see docs/TAROT-REFERENCE.md for sources.
   Pure data and arithmetic - no DOM, no logic beyond the derivations documented here. */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.TarotReference = factory();
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';

  // Index 0-21, character-identical to BirthLore.majorArcana's names, pinned by a test.
  const MAJOR_NAMES = [
    'The Fool', 'The Magician', 'The High Priestess', 'The Empress', 'The Emperor',
    'The Hierophant', 'The Lovers', 'The Chariot', 'Strength', 'The Hermit',
    'Wheel of Fortune', 'Justice', 'The Hanged Man', 'Death', 'Temperance',
    'The Devil', 'The Tower', 'The Star', 'The Moon', 'The Sun', 'Judgement', 'The World'
  ];

  // Suit order is the one the card images use: cards/22.jpg is the Ace of Wands.
  const SUITS = ['Wands', 'Cups', 'Swords', 'Pentacles'];
  const RANKS = ['Ace', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine',
                 'Ten', 'Page', 'Knight', 'Queen', 'King'];

  const inRange = index => Number.isInteger(index) && index >= 0 && index < 78;

  function name(index) {
    if (!inRange(index)) return '';
    if (index < 22) return MAJOR_NAMES[index];
    const offset = index - 22;
    return `${RANKS[offset % 14]} of ${SUITS[Math.floor(offset / 14)]}`;
  }

  const slug = index => name(index).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

  const slugs = new Map();
  for (let i = 0; i < 78; i++) slugs.set(slug(i), i);
  const indexForSlug = value => (typeof value === 'string' && slugs.has(value) ? slugs.get(value) : -1);

  // Chaldean order of the decan rulers from Mars at 0 Aries, identical to
  // classical-engine.js's faceOrder, which a test cross-checks.
  const FACE_ORDER = ['Mars', 'Sun', 'Venus', 'Mercury', 'Moon', 'Saturn', 'Jupiter'];
  const SIGNS = ['Aries', 'Taurus', 'Gemini', 'Cancer', 'Leo', 'Virgo',
                 'Libra', 'Scorpio', 'Sagittarius', 'Capricorn', 'Aquarius', 'Pisces'];

  // The Golden Dawn runs the 36 pips through the zodiac from Aries. Each sign takes its
  // element's suit, and the rank base cycles 2, 5, 8 as the signs advance, so Aries takes
  // Wands 2-4, Taurus takes Pentacles 5-7, Gemini takes Swords 8-10, and so on round.
  const SUIT_OF_ELEMENT = ['Wands', 'Pentacles', 'Swords', 'Cups']; // fire, earth, air, water
  const decans = new Map(); // card index -> {sign, ruler}
  for (let sign = 0; sign < 12; sign++) {
    const suit = SUIT_OF_ELEMENT[sign % 4];
    const base = 2 + 3 * (sign % 3);
    for (let decan = 0; decan < 3; decan++) {
      // RANKS[1] is 'Two', so a rank NUMBER n sits at RANKS index n - 1.
      const index = 22 + SUITS.indexOf(suit) * 14 + (base + decan - 1);
      decans.set(index, {sign: SIGNS[sign], ruler: FACE_ORDER[(sign * 3 + decan) % 7]});
    }
  }

  const SUIT_ELEMENT = {Wands: 'Fire', Cups: 'Water', Swords: 'Air', Pentacles: 'Earth'};
  // Waite's King, Queen, Knight and Page read as element-of-element. This is the form in
  // common use with Waite's deck; the Golden Dawn's own Knight, Queen, Prince and Princess
  // do not map one to one onto it, which docs/TAROT-REFERENCE.md states.
  const COURT_ELEMENT = {King: 'Fire', Queen: 'Water', Knight: 'Air', Page: 'Earth'};

  // Index 0-21. Golden Dawn attributions with Waite's numbering: Strength VIII takes Leo
  // and Justice XI takes Libra. The Crowley exchange of The Star and The Emperor is not used.
  const MAJORS = [
    {letter: 'Aleph',  element: 'Air'},        {letter: 'Beth',   ruler: 'Mercury'},
    {letter: 'Gimel',  ruler: 'Moon'},         {letter: 'Daleth', ruler: 'Venus'},
    {letter: 'Heh',    sign: 'Aries'},         {letter: 'Vau',    sign: 'Taurus'},
    {letter: 'Zain',   sign: 'Gemini'},        {letter: 'Cheth',  sign: 'Cancer'},
    {letter: 'Teth',   sign: 'Leo'},           {letter: 'Yod',    sign: 'Virgo'},
    {letter: 'Kaph',   ruler: 'Jupiter'},      {letter: 'Lamed',  sign: 'Libra'},
    {letter: 'Mem',    element: 'Water'},      {letter: 'Nun',    sign: 'Scorpio'},
    {letter: 'Samekh', sign: 'Sagittarius'},   {letter: 'Ayin',   sign: 'Capricorn'},
    {letter: 'Peh',    ruler: 'Mars'},         {letter: 'Tzaddi', sign: 'Aquarius'},
    {letter: 'Qoph',   sign: 'Pisces'},        {letter: 'Resh',   ruler: 'Sun'},
    {letter: 'Shin',   element: 'Fire'},       {letter: 'Tau',    ruler: 'Saturn'}
  ];

  function attribution(index) {
    if (!inRange(index)) return null;
    if (index < 22) {
      const major = MAJORS[index];
      return {line: major.sign || major.ruler || major.element, kind: 'major', ...major};
    }
    const decan = decans.get(index);
    if (decan) return {line: `${decan.ruler} in ${decan.sign}`, kind: 'decan', ...decan};
    const offset = index - 22;
    const element = SUIT_ELEMENT[SUITS[Math.floor(offset / 14)]];
    const rank = RANKS[offset % 14];
    if (rank === 'Ace') return {line: `The root of the powers of ${element}`, kind: 'ace', element};
    return {line: `${COURT_ELEMENT[rank]} of ${element}`, kind: 'court', element};
  }

  // Standalone reference copy, keyed by card index. Filled in batches; see
  // docs/superpowers/plans/2026-09-13-tarot-reference.md. Every entry describes what the
  // card holds, never what any one deck pictures, because more than one deck ships with this site.
  const REFERENCE = {};

  // the Major Arcana, indices 0-21.
  REFERENCE[0] = 'Zero is not a quantity, and the Fool is the only major that refuses a fixed place in the count; older packs let it sit anywhere, or outside the pack entirely. It stands for unformed potential — the condition of a person before experience has handed them something to defend. Air belongs behind it, a medium that takes the shape of whatever contains it and holds none of its own. Courts that kept a licensed fool were buying a freedom, not tolerating a deficiency: the one who knows least is also the one with nothing to protect. Innocence and exposure arrive here as a single fact seen from two sides.';
  REFERENCE[1] = 'Under Mercury this is the deck’s card of translation: the claim that something held in the mind can be said, and something said can be made. Its concern is competence, the working traffic between intention and matter, skill that actually reaches the world instead of circling inside it. Older accounts never separated the magus from the showman, and this one does not either — persuasion, craft and sleight of hand share most of their technique, and it declines to say which is in use. One is the first assertion in the sequence: the point where a thing stops being possible and starts being done.';
  REFERENCE[2] = 'Where the Magician speaks, this one withholds. It concerns knowledge that exists before language and loses something in the crossing into it: memory, intuition, dream material, the understanding a body arrives at well ahead of its owner. Its real subject is custody — the difference between what is private and what is secret, and the right to leave a thing unstated until it is ready to be stated. Authority here comes of keeping, not displaying, which is why it reads as reserved where a quicker card would look passive. Nothing in it is owed to whoever happens to be asking.';
  REFERENCE[3] = 'Venus here is fertility in the widest sense, not romance: appetite, abundance, and the body treated as a legitimate source of knowledge instead of an inconvenience. The Empress is the argument that creation is physical labour, conducted in time and in matter, by someone who gets tired. Past the labour comes surplus. Nothing can be given away, wasted, enjoyed or wagered out of a supply that exactly meets its obligations, so abundance is the precondition of generosity and not its reward, and wanting a great deal is treated here as productive rather than greedy.';
  REFERENCE[4] = 'The most immovable card in the pack carries Aries, the sign of beginnings, and the contradiction is deliberate. The Emperor’s subject is authority: rule made durable enough to outlast the person exercising it, which is the whole difference between power and government. Law, precedent, the founding of an order and the handing on of it. It makes no argument that authority is good; it asks instead what a particular authority is for and what it answers to, since rule that answers to nothing has stopped being rule and become appetite. Fatherhood appears as an institution, not a relationship.';
  REFERENCE[5] = 'This is the card of mediation. A hierophant stands between a person and whatever they take to be sacred, and the question it puts is whether that position transmits or intercepts. Institutions preserve what individuals lose — a practice survives because someone kept repeating it long after the reason was obvious — and the same repetition flattens what it preserves. Its authority is second-hand by design: the office speaks for something and never as it, so everything on offer here arrives at one remove from the source it points at.';
  REFERENCE[6] = 'Less a card of romance than of terms. Two things joined become a third with requirements of its own, and this one carries both the pull towards union and the narrowing that union costs, since a yes of that size is also a set of noes. What is given up in a joining is rarely what either party expected to give up, and the card is more interested in that miscalculation than in the attraction that preceded it. Older readings turned on a moment of decision, though the older names say only the Lover. Its question is not who a person wants but what they are prepared to be bound by.';
  REFERENCE[7] = 'Cancer, the sign of the shell, sits on the pack’s card of conquest, and the armour is the point. The Chariot holds victory together with its equipment — the discipline, the narrowed attention, the hardened surface that make sustained campaigning possible. What protects also insulates: the shell that keeps an effort intact keeps contact out, and this is presented as a trade, not a free gain. Victory of this kind is public by nature, and the card has no interest in quiet competence. Nothing here is gentle. Gentleness is the next card’s business.';
  REFERENCE[8] = 'The Golden Dawn moved this card to eighth place and set Leo there; Waite published that order, and the attribution says most of what the card is about. Its subject is vitality, the animal heat everything else in a life runs on, and the long unglamorous business of living alongside that heat instead of spending it all at once. Exertion belongs to the Chariot; this is something slower. The capacity to remain with what has not yet yielded, to tolerate discomfort without converting it into a crisis, to keep command of oneself without needing the fact acknowledged. Most of it happens unwitnessed, which is why from outside it can look like nothing is being done.';
  REFERENCE[9] = 'Solitude here is a method, not a mood. Two things sit inside it at once, and neither cancels the other. The first is the guide: someone who has gone further along a road and can report what is there, which is the oldest reason anyone tolerated a hermit at all. The second is the distance that made the guide worth consulting, which is also what makes the return awkward — go far enough for the view and the road back becomes a real question. Understanding arrived at this way is built rather than handed over, which lends it an unusual durability and a particular blind spot, since nothing argued with it on the way.';
  REFERENCE[10] = 'Its subject is a mechanism and not a person, which changes what it can be asked. Medieval writers used the same emblem to make a moral argument: fortune keeps no ledger, rewards nothing, and can withdraw on the same terms it gave. What the card names is the whole category of conditions no one person set and no one person can negotiate with, which is a larger category than most accounts of a life admit. A wheel has one still place in it, and the deck puts that forward as somewhere to stand — not a promise, simply the only part of the turning that is not being turned.';
  REFERENCE[11] = 'The claim underneath this card is that acts have weight and can be compared, that there is a standard outside the person being measured. Libra is the one sign in the zodiac named for an object instead of a creature, and the object is a measuring instrument, which is as near to a definition as the attributions ever get. Its coldness is deliberate. Justice takes no interest in how understandable a reason was, only in what that reason produced. Being understood and being answerable are different requests, and only the second is entertained here.';
  REFERENCE[12] = 'A suspension that was agreed to. Voluntary sacrifice is its whole content: something of value given up on purpose, without guarantees, in exchange for a kind of seeing not available on any other terms. Odin hung nine nights for the runes, and the shape of that arrangement is very old. Of the three majors given an element instead of a planet or a sign, this one takes water, which holds no position of its own. The oddity is that nothing in it happens, and that is precisely the content — it sits one place before Death, and the two have always been read together. What is surrendered is position, not life.';
  REFERENCE[13] = 'The card people most often ask to have softened, and softening it is the one thing that empties it. Death names endings: the point after which something does not continue, which no rewording alters. The reassurance that it only ever means change is half true and half nerves, and it is a modern habit; older readers were blunter. Change is what follows an ending, but the ending is real, it comes first, and some of what ends was loved. Its number matters too: thirteen falls in the middle of the sequence and not at the close, so mortality is a structural fact of a life and not its conclusion.';
  REFERENCE[14] = 'Three of the four classical virtues survive in the majors, and this is the one whose name has aged worst. Temperance was never abstinence; it meant proportion, in the sense of tempering a metal or cutting wine to make it drinkable. Time is its ingredient. The alchemists who owned this vocabulary measured their work in months, and nothing they did could be hurried without spoiling. What it offers is accuracy — the right ratio is a finding, arrived at by trial, not a compromise struck between two positions, and the distance between those two things is most of the card.';
  REFERENCE[15] = 'This card pairs with the Lovers: the same joining, renegotiated on worse terms. What it names is bondage of the sort that was entered into — arrangements that were once chosen and have quietly become the floor. It is not squeamish about appetite and does not moralise about pleasure; the interest is in what has come to be accepted as necessary, which is generally something ordinary and seldom something dramatic. There is comedy in it too. The tempter is an externalised want, and the joke is that the power on that side was never its own.';
  REFERENCE[16] = 'Sudden, external, and not asked for. The Tower names the collapse of something that was built — an arrangement, a certainty, a career, an account of oneself — coming down all at once because the correction was refused in instalments. Its Mars attribution is about speed, not malice: nothing in the card is punitive. It does not say the fall was deserved, and does not offer it as improvement in disguise. What it describes is pressure released from inside a construction that had a flaw in it from the start. The damage is real, and the card does not net it off against whatever comes after.';
  REFERENCE[17] = 'A star is useful precisely because it is far away and cannot be reached. Nothing here can be acquired: this is a card about bearings, a fixed point that stays put while everything nearer to it moves, and it would stop working the moment it came any closer. Distance is the service and not the deprivation. Its place in the order carries the rest of the argument. It follows directly on the Tower, and that is offered as sequence, not reward, since what makes the ground visible again is that something standing on it came down.';
  REFERENCE[18] = 'Borrowed light, and everything that follows from borrowing it. The Moon governs unreliable perception, not another person’s deception but the mind’s own editing, which runs hardest at night and on tired days. The card named for the Moon is not the card the Moon is attributed to — that is the High Priestess — and Pisces holds this one instead, a sign with no fixed edges to speak of. The faculty that distorts a situation is the same one that makes images, and older writers never fully separated lunacy from imagination. Some things are genuinely hidden; others are merely unlit, and from inside the dark the two feel identical.';
  REFERENCE[19] = 'In a pack built largely on what is withheld, here nothing is. The Sun is full disclosure: plain seeing, daylight, the condition in which a thing is simply what it appears to be. That includes whoever is doing the looking, which is the part people forget to want. Childhood belongs here as well, not as innocence but as the period before self-editing begins. Worth noting what it does not offer: clarity is not depth, heat is not gentleness, and the Sun reveals without holding any opinion at all about what has been revealed.';
  REFERENCE[20] = 'Justice weighs a single act; this one takes up a whole life, and the difference between them is the point. Judgement is reckoning of the public and collective kind, a past not erased but read out in the open with nothing edited for comfort. The scene behind it is a resurrection, and that structure survives the loss of its theology: something considered finished is addressed as though it were still live. Fire is the element it carries, the usual marker in this system for a change of state that does not reverse. The severity people feel in it is not condemnation so much as exposure to a complete record, one’s own included.';
  REFERENCE[21] = 'Saturn is the last of the visible planets and the traditional ring around everything, so its weight sits well on the final card. The World holds wholeness, and wholeness is defined by having an edge — a thing is complete when nothing further can be added, which is a limit before it is a triumph. Its claim is total: everything the deck has counted is inside it, with nothing left over and nowhere further to go. Completion is a kind of dispossession as well. A finished thing no longer needs its maker, and the card counts that as the proof and not the loss.';

  // Wands, indices 22-35.
  REFERENCE[22] = 'Its traditional line calls this the root of the powers of Fire. Root is the exact word for it. A root is the buried part and the supplying part, and it resembles none of what grows out of it: a root is not a small version of the plant. What the Ace holds is therefore the suit’s supply and none of its uses — the heat the other thirteen draw on, present undiminished whether they draw on it well, badly, or not at all. The card says nothing about what that heat is for, or whether anybody has yet found a use for it. Every other Wand is a variation played on it.';
  REFERENCE[23] = 'An Ace admits no scale, since nothing stands beside it to be measured against. Two supplies a second term, and size, direction and distance become sayable in the suit for the first time. Comparison is a dispassionate operation, and this is where it enters a suit built for the opposite: the Two sets a move already made against a move not yet made and asks which of them is larger, a question fire has no equipment for and very little patience with. What this card contributes to its suit is measurement, and measurement leaves it unusually still.';
  REFERENCE[24] = 'Most of a Three is elapsed time. The Ace happens at once and the Two is a decision, but a Three has parts that must occur in an order, and ordering takes as long as it takes whether or not anyone is willing to spend it. That is an awkward condition for fire, whose characteristic speed is of no use at all against a process that simply has a length. The stretch this card covers is the one during which the work is neither being done nor finished — waiting that belongs to the task itself, and cannot be delegated, hurried or skipped. Patience here is arithmetic, not virtue.';
  REFERENCE[25] = 'Venus is in detriment in Aries, sitting opposite the Libra it rules, and the pack spends that uncomfortable placement on the suit’s card of settled enjoyment. The friction is the argument. Fours are the number of settlement — corners, enclosure, a shape that holds — and enclosure is close to the last thing fire wants. The claim being made is that a fixed form is what makes pleasure repeatable instead of accidental: a thing done once by luck becomes a thing done again on purpose, which is most of what a custom is. Nobody hands a form of this kind down. The people keeping it are the people who agreed it, which is what stops the enclosure hardening into a wall.';
  REFERENCE[26] = 'Fives break the square. In every suit the Five is where the number stops cohering and the suit meets what it cannot absorb, and in Wands what it meets is itself. What obstructs here is likeness: several efforts pushing in one direction and getting in each other’s way for exactly that reason. Fire against fire is not opposition, and the usual way a disagreement ends — somebody turning out to be right — has nothing here to fasten onto. What makes the card thankless is that the exertion is real and leaves nothing behind to record that it happened, so afterwards it reads as training or as waste with equal plausibility.';
  REFERENCE[27] = 'A reputation is held by other people. It is not a property of whoever it describes, which is the fact this card is built on and the reason it can never be settled from one side alone. Something was done; an account of it now circulates, and the account has its own life, its own errors, and an audience with reasons of its own for repeating it. The gap between an act and its report is where the card sits. Sixes across the pips restore order after the Fives, and the order restored here is a social one: the suit’s exertion becomes a public fact, and public facts are not owned.';
  REFERENCE[28] = 'The Five is a contest among equals; the Seven is not, and the asymmetry changes the terms completely. Holding a position already occupied costs less than taking one, and the cheapness is the trap. An advantage can be kept long after whatever it protected stopped being worth protecting, because the price of continuing stays small enough never to force the question. Sevens are the pips’ point of strain, and here the strain accumulates through duration: a position grows harder to justify the longer it is held, and easier to hold the longer it is justified.';
  REFERENCE[29] = 'Dispatch and arrival are separated by an interval, and that interval is what the Eight is for. Throughout it the matter is out of anybody’s hands, still travelling, and no longer correctable by whoever set it going: intent was fixed at the moment of release, interpretation belongs to whoever receives it, and the space between the two admits no revision. Speed is the property most easily noticed here and the least consequential, since the irreversibility would hold at any pace at all. Most of the suit is concerned with effort; this pip is concerned with what effort does once it has left.';
  REFERENCE[30] = 'A Nine is penultimate. That fact does the whole of the arguing. The hardest part of a long undertaking is rarely its worst moment; it is the stage just short of the last, which carries the accumulated cost of everything already spent and none of the relief of being over. By that point the reasons that began the thing have worn thin while the obligations it generated have not, and the two no longer match each other. The fatigue it names is specific to lateness — an effort that has already proved it can be sustained, now being asked to sustain itself a little further on reserves nobody has any way of estimating.';
  REFERENCE[31] = 'A Ten is a suit taken as far as it goes. Each one overdoes its own suit’s principle; in Wands the principle is accumulation. Enthusiasm generates commitments faster than anything discharges them, and the suit carries no mechanism for closing one out, so every undertaking it ever started is still open and only the total ever moves. That is what makes the load so hard to argue with. No single item on it is unreasonable and none of it arrived uninvited, so nothing on the list answers to being called the problem. The suit ends by counting.';
  REFERENCE[32] = 'Earth is the element that stays where it is put, and earth of fire is where the suit acquires a location: somewhere for heat to be kept, which is the difference between a beginner and a flare. In the households these ranks come from, a page was a post before it was an age — an attachment to somebody else’s work, learning by proximity and by doing the small end of it for years. That is the shape of the card. Its subject is apprenticeship, a relation with a duration and an obligation inside it, in which being unskilled is the arrangement itself.';
  REFERENCE[33] = 'Air of fire. Air is what fire feeds on, so nothing in this court qualifies anything else, and the two halves of the attribution simply agree. Air contributes reach as well as increase, being the element of direction and of distance, and it carries. This court supplies force with a bearing and no ballast — able to cover ground the suit could not otherwise reach, and unable to remain anywhere it arrives, because whatever sustains the motion is the same stuff being burnt to produce it.';
  REFERENCE[34] = 'Pairing fire with the element that puts it out needs explaining. The explanation is rate. Water does not only quench: it conducts heat and carries warmth through a mass without being spent in the carrying. What that gives the suit is temperature instead of flame — something that can be maintained at a level for years. The court’s subject is climate: what a person is consistently like alters what becomes possible near them, with no instruction issued, nothing requested, and generally nobody noticing the mechanism. Influence like this is never exercised. It is simply the conditions.';
  REFERENCE[35] = 'Each of the four doubled courts says what an element is when nothing tempers it. Fire of fire is that claim made about this suit. Unmixed, fire is the thing that must be supplied in order to continue and that uses up whatever supplies it. Authority built on that runs on a standing intake of the new: fresh undertakings, fresh conviction, fresh people who find it convincing. What the pack sets down here is the entire arrangement, including the part usually left out of the account — where the intake comes from, and what it costs whoever is providing it.';

  // Cups, indices 36-49.
  REFERENCE[36] = 'An Ace carries no decan. The tradition hands it a quadrant of the heavens instead, three signs wide — an authority stated at the largest scale the system has and the least specific. At that scale the suit’s subject is receptivity, and the pack has to begin by arguing for it, since its grammar treats the other three elements as things done to the world and this one as the capacity to be reached by it. Susceptibility is entered here as an ability, unqualified by occasion, object or cost. The thirteen cards that follow supply all three.';
  REFERENCE[37] = 'A pair has no majority in it. Nothing inside a two can be settled by weight of numbers, so every agreement one reaches has to be unanimous, and neither party can be outvoted, outwaited or carried along by a bloc. The arrangement is correspondingly sturdy and correspondingly exposed — agreement is the whole of what holds it up, and it is renewable at will from either side, without notice and with no procedure to appeal to. Every larger grouping in the suit has machinery for carrying a member who has stopped agreeing. That machinery begins one size up.';
  REFERENCE[38] = 'A feeling held in common is not one feeling multiplied. Some part of each person’s share is made of the others having it, so what circulates is reflexive and cannot be traced back to a source: nobody present began it and everybody present is keeping it going. Company differs from proximity on exactly this point, and the difference has little to do with how much anyone is enjoying themselves. It also sets the terms the Three works under. Something held jointly answers to more than one account of itself, and no member of the group has the standing to say what it was.';
  REFERENCE[39] = 'Any faculty that reports a change stops reporting a constant. A steady supply, undiminished and entirely intact, gradually ceases to register at all, leaving the odd condition of dissatisfaction with no grievance attached — nothing has gone wrong, nothing has been taken away, and the flatness persists regardless, with no object to fasten itself to. Grievance is a form of explanation, and the Four withholds one, leaving the state peculiarly hard to examine: examination generally begins by naming a fault, and here there is no fault to name. Habituation is a property of the instrument doing the sensing.';
  REFERENCE[40] = 'Mars rules Scorpio, which makes this face of it that placement doing precisely what it is equipped for: a subtraction performed cleanly, with no error in it to appeal against. The Five’s subject is what goes on working afterwards — an attachment that does not dissolve when its object does, still operating with nothing left to operate on. Grief is the name for that residue, and its size is a measurement of the worth of what is gone. The Five sets out the stretch of time in which a person goes on being attached to something that has stopped being there.';
  REFERENCE[41] = 'Care received before it could be earned leaves an obligation with nobody to discharge it to. Whoever supplied it was not keeping count, or is no longer available to be repaid, and the debt stands regardless, which leaves it one direction to travel: sideways or forwards, towards someone who had no part in incurring it. The Six has always carried gifts and early kindness, and the faint unease that accompanies them belongs to the same mechanism. An inheritance of this sort is an asymmetry running one way through time. Gratitude here has nowhere to be delivered.';
  REFERENCE[42] = 'Wanting is not a waiting room for having. It is a condition with satisfactions of its own, chief among them that anything still wanted has yet to disappoint, which gives it a standing advantage over whatever is already to hand. Where an appetite cannot reach the thing it is for, it multiplies the things it is for, and the multiplying is enjoyable in itself — the field widens because widening it is the pleasurable part of the operation. Venus takes the last face of Scorpio here, desire at its most concentrated and its least practical. The appetite the Seven names is an appetite for possibility, which no particular possibility would satisfy.';
  REFERENCE[43] = 'Saturn is the pack’s account-keeper; Pisces dissolves the terms an account would be kept in. The Eight sits on that contradiction. Leaving something that has not failed forfeits the ordinary justification — nobody defaulted, nothing broke — and the vocabulary available for departure is borrowed almost wholly from the vocabulary of complaint. With no complaint to draw on, the entire reason has to be carried by whoever holds it, unshared and unratified by anybody else. A departure of that kind is heavier than one with a grievance behind it, not lighter. The Eight marks the distance between a reason and an excuse. The excuse is the part that is missing.';
  REFERENCE[44] = 'Nothing can be lost until it has been had. The Nine is the point at which the suit stops reaching and holds something, and holding introduces an exposure that did not exist while the thing was still out of reach: a state that can be kept is a state that can be taken. The exposure is proportionate to the contentment, since the same holding is what both are measured against. Anyone totting up what has come together is by the same act totting up what is now available to go. The Nine’s plenty is lodged in a person, which is a perishable place to keep anything.';
  REFERENCE[45] = 'The obvious maximum for a water suit would be depth. The Ten counts in years. The arrangement it describes has to outlast the feeling that founded it — a household, a long friendship, anything obliged to keep working on the days when nobody inside it feels warmly towards anybody else. Mars takes the final face of Pisces, putting the element of effort at the close of the suit of merging, which is the pack admitting that something has to do the work on those days. Usually it is habit, the accumulated weight of having gone on before, and habit is indifferent to how anybody happens to feel this week. Most of what such an arrangement has is the length of time it has already run.';
  REFERENCE[46] = 'Earth is the term that comes in pieces. Any quantity of water is like any other quantity of water, and the same holds for fire and for air; earth is granular, and one part of it is not another. Particularity is what that adds to a water suit — feeling with an object, about this and not about the general condition of being open to anything. A capacity cannot be mistaken, and neither can a mood, since neither of them is about anything at all. A particular is about something, and being about something is what makes being wrong possible. Error becomes available to the suit at this rank.';
  REFERENCE[47] = 'A borrowed form is silent about what lies behind it. The symmetry runs both ways: someone practised can produce the form with nothing behind it at all, and someone with a great deal behind them can produce little that resembles it. Knighthood ran on a form of exactly that kind, a code of conduct entirely separable from the sentiment it was supposed to carry. Separability is what makes such a code useful. A convention supplies a way of acting before anybody involved knows what is warranted, the person acting included. The Knight is the move that can be made while the feeling behind it is still unreadable.';
  REFERENCE[48] = 'Doubling an element removes the second term that would otherwise describe it, so this court has to be read off what water does to whatever enters it. Water dissolves without destroying: what goes into solution is carried whole and comes back out unchanged, which is a fair description of the rank’s function — taking something in entire without turning it into something else along the way. The limit is a chemical one, and it is exact. A solution saturates, and the concentration at which it does so was never anybody’s decision.';
  REFERENCE[49] = 'Fire of water describes a mechanism with a fault built into it. Fire supplies the part that acts and water the part that registers, so the rank must arrive at decisions using an instrument which cannot be switched off and cannot be taken at face value. Feeling is admissible evidence here, and frequently the only evidence of what is genuinely at stake — but it is evidence from a participant, and a participant’s testimony gets weighted rather than believed outright or struck from the record. The difficulty here is arithmetic of that sort. Nothing is being suppressed; something is being priced.';

  // Swords, indices 50-63.
  REFERENCE[50] = 'An edge is what a boundary becomes when it is given a material to run through, and the Ace holds that before it has been put to any use — the bare ability to draw a line across ground that a moment earlier ran continuous. Every distinction is a small violence done to something whole, and the suit is candid about it, arguing only that the violence is the price of thinking at all. A surveyor’s line has no thickness and the field on either side of it is the same field; the line is still the thing people go to law about. Sharpness, in this suit, is a measure of how fine a difference can be held.';
  REFERENCE[51] = 'Cut something once and two things exist where one did before, and the pair looks native almost at once, as though the world had come divided that way and the division had merely been noticed. That is the Two’s business. A question put as a choice between two options has already had most of its work done on it, out of sight, by whoever settled that there were two; everything the cut discarded is gone before the choosing begins, and leaves no mark on the alternatives that remain. A ballot paper with two names on it records a decision taken earlier, elsewhere, by fewer people.';
  REFERENCE[52] = 'Some pain has nothing broken underneath it. The sorrow this suit deals in is cognitive: the body has been left alone, and a person understands something now that they understood differently an hour ago. The mind keeps no procedure for unknowing. A thing once grasped can be set aside, argued with, or left unmentioned for decades, and none of that returns anyone to the condition of not having grasped it. Saturn takes its exaltation in Libra, the one sign the tradition honours it in, and that honour is spent here. Nobody did this to anyone. Something became true and was afterwards found out, in that order.';
  REFERENCE[53] = 'Ground left fallow is being kept out of use, which is an arrangement with a purpose behind it: idleness puts nothing back into the soil, it only stops more being drawn out, and the stock recovers because the demand stopped. The Four applies that to attention. A mind cannot be instructed to stop; it can only be left without material, and what the interval returns is proportion — the size of a difficulty relative to everything else, a judgement unavailable from inside the work. Convalescence is the ordinary name for the arrangement: a stretch of time with a start, an end, and one instruction, which is to stay put.';
  REFERENCE[54] = 'Being out-argued and being convinced look identical from outside and are not the same event. At the Five an exchange stops because one side has run out of material, and the suit’s instrument — the better argument — turns out to settle only the argument. The mechanism never reaches whatever was actually in dispute, which was generally not a proposition at all. Victory of this shape is a fact about the proceedings. The side that stopped talking has not moved, and now holds a grievance it did not hold before, arising from the manner rather than the matter. What ends at the Five is the exchange. The disagreement was never a party to it.';
  REFERENCE[55] = 'Departure is logistics before it is anything else: what can be carried, who is going, in what order, and what has to be left behind to make the rest portable. The Six is that stage. Its peculiarity is that a passage of real consequence gets conducted almost wholly through small practical decisions, not one of which resembles the size of the thing being done. The practical questions get asked first and answered first, generally by people in no condition to answer anything. Grief and packing occupy the same afternoon, and it is the packing that gets anybody anywhere.';
  REFERENCE[56] = 'A thing kept from a group has to be kept repeatedly. Concealment is maintenance: it is performed again at every occasion where it might come out, and the work scales with how many people must not know and for how long. The Seven counts that arrangement as an expense rather than as a manoeuvre. Moon in Aquarius sets the pack’s most private body among assemblies and shared rules — something personal carried through machinery built for what everyone holds together. An alibi has to be produced in the same words every time it is asked for, and the remembering is a job for one person.';
  REFERENCE[57] = 'From here the suit turns its instrument on the person holding it. The first seven cards apply division outward, to options and disputes and other people; the Gemini decans — the Eight, the Nine and the Ten — apply the same faculty inward, where it works just as well. A capacity for finding the flaw in an argument finds the flaws in its owner at the same rate and with the same accuracy. Jupiter sits in detriment in Gemini, the planet of the large view in the sign that works at close range, which is the Eight’s difficulty exactly: the analysis is sound and its subject is the analyst.';
  REFERENCE[58] = 'An event occurs once and has a size. The expectation of it can be run any number of times and never acquires one; what accumulates across the repetitions is not evidence, though from the inside it is hard to tell the difference. Mars in Gemini puts the planet equipped for one decisive blow into the sign that does everything twice — force with nothing to land on and no instruction to halt. The faculty doing this is the ordinary one that makes any planning possible, working on material it cannot settle. Rehearsal is how a difficult passage is learned, and the Nine is that same mechanism applied to a passage that exists only in the person rehearsing it.';
  REFERENCE[59] = 'Arguments run out. The Ten is what is left when they have: a matter closed by exhaustion rather than by verdict, every reason gone through and each of them leaving things where they already were. It registers as flatness more often than as pain, pain being partly the activity of still contesting something. A suit that works by taking things apart arrives at last at a thing entirely taken apart, no version of it left whole enough to work with further. The older lists set down ruin, and the ending of a matter, and stopped there, which is an accurate place to stop.';
  REFERENCE[60] = 'Writing a thought down changes its status. Until then it can be revised silently, and its owner can honestly hold several versions at once; committed to a surface it becomes one version, in one order, with a date attached. The Page is the rank at which that becomes possible for the suit: a thought given an outside, available to people who were not there when it formed. Most of what gets called rigour follows from that single change, since a position cannot be compared with itself until two dated copies exist. A question written down in March can be read again in November, and in November it is still the same question, whatever has become of the mood that asked it.';
  REFERENCE[61] = 'Every reply has to engage the one before it, and twenty minutes of that leaves the thing under contest a remark made ten minutes ago rather than the question anybody arrived with. An exchange develops a gradient, and it runs away from the subject. The other three courts in this suit each carry a second element that sits outside the talking and can be consulted; air of air carries none, so the only thing a move here can be checked against is the move before it. Each step follows correctly, every participant has behaved impeccably, and the position finally reached would be unrecognisable to whoever opened. A transcript read a year later is largely about itself.';
  REFERENCE[62] = 'Accuracy is not popular. Anyone who reliably says the exact thing rather than the comfortable one ends up standing slightly apart from every group that needs them, and the position is produced by the function, not by any hardness in the person occupying it. Older cartomantic lists handed this rank widowhood, privation and mourning, and offered no reason for it; those were the terms such lists used for a woman standing outside an arrangement, and they belong to the card’s history rather than to anybody who draws it. Precision at that level is trained, in the way a craft is trained, by being corrected. Nobody thanks the person at the time.';
  REFERENCE[63] = 'Deliberation has no natural stopping point. Reasons can be produced indefinitely, each of them legitimate, and nothing inside the reasoning indicates when enough of it has been done: a further consideration is always available, so the process cannot be relied on to choose the moment it ends. Fire of air supplies that ending — an act performed on the deliberation rather than derived from it, and the closing of a question is therefore never justified by the question. Decide is a cutting word, from caedere, to cut off. It came into English already meaning to bring a dispute to an end.';

  // Pentacles, indices 64-77.
  REFERENCE[64] = 'A thought can be handed over and still be held; so can a feeling, and so can a plan. An amount cannot. Matter is rivalrous — two things will not occupy one place, and what one person holds is by that fact not available to anyone else — and the suit begins from that property, before any use has been made of it. Cost comes out of it, and ownership, and the entire apparatus of keeping track. None of it is moral, which is worth saying at the outset, since the suit gets read that way so often. Earth at its root is the condition of being somewhere in particular, in some quantity, rather than everywhere in principle.';
  REFERENCE[65] = 'On Friday the only figure that counts is the one that can be produced. A person can be owed more than they owe and still be unable to pay, because solvency and liquidity are separate properties and the Two names the distance between them: the money is real, the timing is not arranged. Figures that ought to describe the same holding come apart because they are separated in time. Jupiter, which enlarges, takes the first face of Capricorn, a sign ruled by the planet of deadlines, and enlargement is no use whatever against a date. The question the Two puts is when, not how much, and a sum does not state that about itself.';
  REFERENCE[66] = 'Three points fix a plane. That is the first thing a Three does in any material: it produces an arrangement that can no longer be adjusted at one corner on its own. Before it, parts are merely adjacent; after it they are a structure, and a structure means each element has surrendered the motion it had while separate, the gain in rigidity being exactly the loss of independent play. Work carried out by several hands reaches this condition early and without announcement. Once the parts are taking load from one another, altering any one of them is a proposal about all of them, which is why the disagreements stop being about anybody’s own piece.';
  REFERENCE[67] = 'A store exists in order to be run down, and running it down looks exactly like going backwards. The figures record no difference between a reserve doing the work it was assembled for and a reserve simply being lost — both arrive as a smaller number than last year — so the person who built it meets its correct use as damage. The Four therefore contains an instruction its keeper is disposed to disobey: hold until the bad year, then spend. The first half was rewarded every time it was obeyed and the second half never is. Nobody is congratulated for the year the savings ran out, which is the year they worked.';
  REFERENCE[68] = 'Everything costs more in small quantities. Arrangements that would hold for a year have to be remade every week, and the attention it would take to get out of the position is spent staying in it — a mechanism rather than a failing, and it works the same way on whoever is in it. The card’s other half is exclusion, which is a separate fact: a provision exists, a threshold stands in front of it, and being outside a thing is a different condition from its not existing. Nothing in the Five is offered as a lesson. The hardship is literal — rent, warmth, food — and that is the level the card asks to be read at before any other.';
  REFERENCE[69] = 'Before it was a virtue, giving was compulsory. Tithes were owed whether or not anybody felt charitable, parishes assessed their own households, and relief was handed out by officers working from a ledger — so the disposition of the giver did not enter into it, and the recipient held a settled claim on a particular parish rather than a hope of somebody’s good opinion. The Six is old enough to carry that arrangement and has outlived it. Moving relief into private hands moved the discretion along with it, and discretion is exercised in person, by one party looking at another. The parish decided where a person belonged, and that was the test.';
  REFERENCE[70] = 'Half a harvest is food. Half a tunnel is not. Some undertakings return value in proportion to how far they have got, and others return nothing whatever until the last piece is in, and while the work is going on the two conditions feel identical from inside — the same effort spent, the same thing not yet there. Which kind a project is was settled by its nature long before anyone started on it, and it decides what an interruption costs: in one case a delay, in the other everything already put in. Nobody is told which kind they are working on. It belongs to the work itself, and it holds whether anybody has thought to ask or not.';
  REFERENCE[71] = 'A great many English surnames are jobs — Smith, Fletcher, Cooper, Chandler, Turner — and they descended, so the trade outlived whoever first answered to it. For most of the period this pack comes out of, a trade fixed the street a person lived in, the company they belonged to and who buried them; it was carried rather than performed. That is the older order the Eight belongs to, and the rank is the place where an activity and the person doing it stop coming apart cleanly. Later usage separated them again, and the card now reads as counsel about application. The surnames survived the trades.';
  REFERENCE[72] = 'Two people can hold the same object and get different prices for it, and the difference is which of them can afford to wait a month. The one who must sell today is negotiating against a clock the other cannot hear. Self-sufficiency, at the rank where the suit arrives at it, is largely that — not a quantity so much as a set of offers that can be turned down. Venus takes the middle face of Virgo here, at her weakest in a sign that inspects and sorts, so the ease this rank holds is ease that has been through an inspection.';
  REFERENCE[73] = 'At the Ten the thing that owns property stops being a person. A house, a firm, a name on a lease — the holder is an entity that outlasts any of its members, and once it exists, decisions get taken on its behalf by people who will not be there for the result: what to sell, what to keep intact, which of the next lot to train for it. Mercury in Virgo is the temper such an arrangement requires, because the whole of it is administration. The individuals are then occupants of roles built to have someone in them, and the arrangement is indifferent as to which of them it is. Its interests are real and they are nobody’s.';
  REFERENCE[74] = 'Earth of earth runs on the longest clock in the pack, and the rank holding it is the youngest in the suit. That pairing is the argument. Soil, a trade, a sum put by — each makes the calendar the operative term, so the earliest decision in this suit outweighs every later one, not because it is wiser but because more time remains for it to work in. That is an odd endowment for a beginner: the suit’s largest lever sits with the rank that has the least idea what to do with it. An orchard is indifferent to when it was planted; the planter is not.';
  REFERENCE[75] = 'Wind works on stone in amounts that no single day records. Air of earth names that relation exactly: an agent too light to matter set against a material too heavy to shift, with the effect living entirely in how many times it happens rather than in what happens. A court built on it has an awkward relation to its own evidence, because nothing available on a given afternoon resembles what is being produced. Such work cannot be judged by how it feels at the time; the instrument that reports honestly on it is an interval long enough to hold a great many afternoons. Valleys are cut this way.';
  REFERENCE[76] = 'A made thing has a finish date; a kept thing has an interval. Those are different relations to time, and only the first leaves anything that can be pointed at afterwards, since the second produces the continued existence of what was already there. Most of what holds a household or a business together is of the second kind: it cannot be completed, only brought up to date, and from the moment it is up to date it begins falling behind again. The unit of such work is the cycle rather than the piece, and that is why it resists being described as an achievement at all. A roof maintained for thirty years and a roof that has never needed anything look the same from the street.';
  REFERENCE[77] = 'A bridge of twice the span is not a bridge twice as good. Loads grow faster than the members that carry them, and past a certain length the design has to become a different design rather than a larger one. Material arrangements behave like this in general: what worked at one size is not the same thing at four times the size, because the people required, the failure modes and the amount that cannot be done by hand all move at rates of their own. Fire of earth is the suit’s term for will laid on matter, and the King is the size at which will stops being able to touch the matter directly. Whoever built the thing is by then employed on an object that no longer resembles the one they built.';

  const entry = index => (inRange(index)
    ? {reference: REFERENCE[index] || '', attribution: attribution(index)}
    : null);

  return {MAJOR_NAMES, SUITS, RANKS, REFERENCE, name, slug, indexForSlug, attribution, entry};
});
